// Каталог товаров (в реальном проекте — БД или файл).
const items = [
    { id: 1, name: "Ноутбук",     category: "tech",  price: 1500 },
    { id: 2, name: "Яблоко",      category: "fruit", price: 2 },
    { id: 3, name: "Клавиатура",  category: "tech",  price: 80 },
    { id: 4, name: "Банан",       category: "fruit", price: 1 },
    { id: 5, name: "Монитор",     category: "tech",  price: 300 }
];

const q = msg.req.query || {};
let limit = items.length;

if (q.limit !== undefined) {
    limit = Number(q.limit);
    if (!Number.isInteger(limit) || limit < 1 || limit > 5) {
        msg.statusCode = 400;
        msg.headers = { "Content-Type": "application/json; charset=utf-8" };
        msg.payload = {
            error: "Bad Request",
            message: "Параметр limit должен быть целым числом от 1 до 5",
            received: q.limit,
            student: "Крупа Ксения"
        };
        return msg;
    }
}

let result = items;
if (q.category !== undefined) {
    result = result.filter(function (i) { return i.category === q.category; });
}
result = result.slice(0, limit);

msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
msg.payload = {
    student: "Крупа Ксения",
    lab: 2,
    appliedLimit: limit,
    appliedCategory: q.category || null,
    count: result.length,
    items: result
};
return msg;

const items = [
    { id: 1, name: "Ноутбук",     category: "tech",  price: 1500 },
    { id: 2, name: "Яблоко",      category: "fruit", price: 2 },
    { id: 3, name: "Клавиатура",  category: "tech",  price: 80 },
    { id: 4, name: "Банан",       category: "fruit", price: 1 },
    { id: 5, name: "Монитор",     category: "tech",  price: 300 }
];

const raw = msg.req.params.id;
const id = Number(raw);

msg.headers = { "Content-Type": "application/json; charset=utf-8" };

if (!Number.isInteger(id)) {
    msg.statusCode = 400;
    msg.payload = {
        error: "Bad Request",
        message: "id должен быть целым числом",
        received: raw,
        student: "Крупа Ксения"
    };
    return msg;
}

const item = items.find(function (i) { return i.id === id; });

if (!item) {
    msg.statusCode = 404;
    msg.payload = {
        error: "Not Found",
        message: "Товар с id=" + id + " не найден",
        availableIds: items.map(function (i) { return i.id; }),
        student: "Крупа Ксения"
    };
    return msg;
}

msg.statusCode = 200;
msg.payload = {
    student: "Крупа Ксения",
    lab: 2,
    item: item
};
return msg;
